css:
.snowline-home { --journey-height: calc(100dvh - 4rem); --ice-blue: #176b8d; --study-green: #247568; --dawn-coral: #a63f2f; --sun-gold: #7d5600; --night-violet: #58458d; position: relative; height: var(--journey-height); overflow: hidden auto; scroll-behavior: smooth; scroll-snap-type: y mandatory; overscroll-behavior-y: contain; background: var(--page); }
.snowline-home[data-panel-overflow] { scroll-snap-type: y; }
.snowline-home[data-panel-overflow] .snowline-panel { scroll-snap-stop: normal; }
:root[data-theme="dark"] .snowline-home { --ice-blue: #63c6e8; --study-green: #79cdb5; --dawn-coral: #ff9279; --sun-gold: #f2be4a; --night-violet: #b6a2ef; }
.snowline-panel { --scene-accent: var(--accent); --scene-secondary: var(--ice-blue); position: relative; display: flex; min-height: var(--journey-height); overflow: clip; scroll-snap-align: start; scroll-snap-stop: always; isolation: isolate; background: var(--page); }
.snowline-hero { --scene-accent: var(--dawn-coral); --scene-secondary: var(--dawn-coral); }
.snowline-technical { --scene-accent: var(--ice-blue); --scene-secondary: var(--ice-blue); }
.snowline-study { --scene-accent: var(--study-green); --scene-secondary: var(--study-green); }
.snowline-life { --scene-accent: var(--sun-gold); --scene-secondary: var(--sun-gold); }
.snowline-night { --scene-accent: var(--night-violet); --scene-secondary: var(--night-violet); }
.journey-panel-inner { position: relative; z-index: 2; display: flex; width: min(100% - 6rem, 76rem); min-height: var(--journey-height); flex-direction: column; justify-content: center; gap: clamp(1.5rem, 3.5vh, 2.75rem); margin-inline: auto; padding-block: clamp(2rem, 5vh, 4rem); }
.journey-landscape { position: absolute; z-index: 0; inset: 0px; width: 100%; height: 100%; pointer-events: none; }
.terrain-face { --terrain-pigment: var(--scene-accent); --terrain-color: color-mix(
    in srgb,
    var(--terrain-pigment) var(--terrain-ink),
    var(--terrain-paper)
  ); --terrain-outline: color-mix(in srgb, var(--scene-accent) 30%, var(--terrain-color)); fill: color-mix(in srgb, var(--terrain-color) 94%, black); stroke: color-mix(in srgb, var(--terrain-outline) 92%, white); stroke-width: 0.8; stroke-linejoin: round; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.terrain-shade-0 { --terrain-ink: 2%; --terrain-paper: var(--surface); }
.terrain-shade-1 { --terrain-ink: 5%; --terrain-paper: color-mix(in srgb, var(--surface) 65%, var(--surface-subtle)); }
.terrain-shade-2 { --terrain-ink: 8%; --terrain-paper: var(--surface-subtle); }
.terrain-shade-3 { --terrain-ink: 12%; --terrain-paper: var(--surface-subtle); }
.terrain-shade-4 { --terrain-ink: 17%; --terrain-paper: var(--surface-subtle); }
.terrain-shade-5 { --terrain-ink: 23%; --terrain-paper: var(--surface-subtle); }
.terrain-material-trail { --terrain-paper: var(--surface); }
.terrain-material-stone { --terrain-paper: var(--page); }
.terrain-material-marker { --terrain-color: color-mix(
    in srgb,
    var(--scene-accent) calc(18% + var(--terrain-ink)),
    var(--surface-subtle)
  ); }
.terrain-material-track { --terrain-ink: 28%; --terrain-paper: var(--surface-subtle); }
:root[data-theme="dark"] .terrain-face { fill: oklch(from var(--terrain-color) var(--terrain-lightness) var(--terrain-chroma) h); stroke: oklch(from var(--scene-accent) 0.754312 0.078441 h); stroke-opacity: var(--terrain-line); }
:root[data-theme="dark"] .terrain-shade-0 { --terrain-lightness: 0.180976; --terrain-chroma: 0.00805; --terrain-line: 0.16; }
:root[data-theme="dark"] .terrain-shade-1 { --terrain-lightness: 0.196782; --terrain-chroma: 0.012113; --terrain-line: 0.16; }
:root[data-theme="dark"] .terrain-shade-2 { --terrain-lightness: 0.218984; --terrain-chroma: 0.013724; --terrain-line: 0.3; }
:root[data-theme="dark"] .terrain-shade-3 { --terrain-lightness: 0.222338; --terrain-chroma: 0.014546; --terrain-line: 0.3; }
:root[data-theme="dark"] .terrain-shade-4 { --terrain-lightness: 0.255929; --terrain-chroma: 0.019594; --terrain-line: 0.46; }
:root[data-theme="dark"] .terrain-shade-5 { --terrain-lightness: 0.277957; --terrain-chroma: 0.021607; --terrain-line: 0.46; }
:root[data-theme="dark"] .journey-landscape { opacity: 1; }
.journey-landscape path, .journey-landscape circle { vector-effect: non-scaling-stroke; }
.landscape-snow-seam, .landscape-horizon { fill: none; stroke: var(--scene-secondary); stroke-width: 1.05; opacity: 0.56; vector-effect: non-scaling-stroke; }
.landscape-contours, .landscape-strata, .landscape-wind, .landscape-survey-grid, .landscape-survey-marks, .landscape-constellation, .landscape-tent { fill: none; stroke: var(--scene-secondary); vector-effect: non-scaling-stroke; }
.landscape-contours { stroke-width: 0.7; opacity: 0.16; }
.landscape-strata { stroke-width: 0.75; opacity: 0.13; }
.landscape-wind { stroke-width: 0.75; stroke-linecap: round; opacity: 0.16; animation: 12s ease-in-out 0s infinite alternate none running landscape-wind-drift; transform-box: fill-box; transform-origin: center center; }
.landscape-orbit { fill: none; stroke: var(--scene-accent); stroke-width: 0.65; opacity: 0.12; vector-effect: non-scaling-stroke; }
.landscape-orbit circle:first-child { fill: color-mix(in srgb, var(--scene-accent) 18%, transparent); stroke: none; }
.landscape-survey-grid { stroke-width: 0.6; stroke-dasharray: 2, 9; opacity: 0.075; }
.landscape-survey-marks { stroke-width: 0.8; opacity: 0.2; }
.landscape-summit-flag { fill: none; stroke: var(--dawn-coral); stroke-linejoin: round; stroke-width: 1; opacity: 0.72; vector-effect: non-scaling-stroke; }
.landscape-summit-flag path:last-child { fill: color-mix(in srgb, var(--dawn-coral) 72%, transparent); }
.landscape-expedition-route, .landscape-traverse-track { fill: none; stroke: var(--scene-accent); stroke-width: 0.85; stroke-dasharray: 3, 9; opacity: 0.3; vector-effect: non-scaling-stroke; animation: 16s linear 0s infinite normal none running landscape-route-flow; }
.landscape-route-dots circle { fill: var(--page); stroke: var(--scene-accent); stroke-width: 0.9; opacity: 0.62; vector-effect: non-scaling-stroke; animation: 4.8s ease-in-out 0s infinite normal none running landscape-node-breathe; transform-box: fill-box; transform-origin: center center; }
.landscape-route-dots circle:nth-child(2n) { animation-delay: -2.4s; }
.landscape-track-marks { fill: var(--scene-accent); opacity: 0.22; }
.landscape-drift-particles { fill: var(--scene-accent); opacity: 0.3; }
.landscape-drift-particles circle { animation: 8s ease-in-out 0s infinite alternate none running landscape-particle-drift; transform-box: fill-box; transform-origin: center center; }
.landscape-drift-particles circle:nth-child(2n) { animation-delay: -3.5s; }
.landscape-star { fill: var(--scene-accent); opacity: 0.36; animation: 5.5s ease-in-out 0s infinite normal none running landscape-star-twinkle; transform-box: fill-box; transform-origin: center center; }
.landscape-star-lg { fill: var(--scene-accent); opacity: 0.62; }
.landscape-star:nth-child(3n+2) { animation-delay: -2s; }
.landscape-star:nth-child(3n) { animation-delay: -4s; }
.landscape-constellation { stroke: var(--night-violet); stroke-width: 0.65; opacity: 0.24; }
.landscape-constellation circle { fill: var(--page); stroke: var(--night-violet); stroke-width: 0.8; }
.landscape-moon circle:first-child { fill: color-mix(in srgb, var(--scene-accent) 26%, transparent); }
.landscape-moon circle:last-child { fill: color-mix(in srgb, var(--page) 88%, transparent); }
.landscape-camp-glow circle:first-child { fill: color-mix(in srgb, var(--scene-accent) 15%, transparent); }
.landscape-camp-glow circle:last-child { fill: color-mix(in srgb, var(--scene-accent) 28%, transparent); }
.landscape-tent { stroke: var(--scene-accent); stroke-width: 0.9; opacity: 0.38; }
.journey-landscape-cover { opacity: 0.92; }
.journey-landscape-ridge { opacity: 0.78; }
.journey-landscape-field { opacity: 0.78; }
.journey-landscape-camp { opacity: 0.68; }
.journey-eyebrow { margin: 0px; color: var(--scene-accent, var(--accent)); font-size: 0.62rem; font-weight: 780; letter-spacing: 0.18em; text-transform: uppercase; }
.journey-chapter-marker { position: absolute; z-index: 3; top: clamp(2rem, 5vh, 4rem); right: 0px; display: grid; justify-items: end; color: var(--scene-accent); text-align: right; }
.journey-chapter-marker > span { font-size: clamp(4.2rem, 7.5vw, 7.2rem); font-weight: 250; line-height: 0.72; letter-spacing: -0.08em; opacity: 0.2; }
.journey-chapter-marker div { display: flex; flex: 0 0 auto; align-items: center; gap: 0.8rem; margin-top: 0.9rem; }
.journey-chapter-marker strong, .journey-chapter-marker small { font-size: 0.61rem; letter-spacing: 0.14em; }
.journey-chapter-marker small { color: var(--muted); }
.journey-chapter-heading { max-width: min(42rem, 65%); }
.journey-chapter-heading h2 { margin: 0.45rem 0px 0px; font-family: var(--font-reading); font-size: clamp(2.8rem, 5.2vw, 4.7rem); font-weight: 540; line-height: 0.98; letter-spacing: -0.045em; }
.journey-chapter-heading > p:last-child { max-width: 35rem; margin: 0.75rem 0px 0px; color: var(--muted); font-size: 0.88rem; line-height: 1.65; }
.journey-chapter-heading h2:focus-visible { outline: none; text-decoration-line: underline; text-decoration-color: var(--scene-accent); text-decoration-thickness: 1px; text-underline-offset: 0.14em; }
.journey-section-label { display: grid; grid-template-columns: minmax(0px, 1fr) auto; align-items: baseline; gap: 0.65rem; padding-bottom: 0.65rem; border-bottom: 1px solid var(--line); }
.journey-section-label h3 { margin: 0px; font-size: 0.68rem; font-weight: 760; letter-spacing: 0.13em; text-transform: uppercase; }
.journey-section-label h3 a { color: inherit; text-decoration: none; }
.journey-scroll-controls { display: inline-flex; align-items: center; gap: 0.25rem; }
.journey-scroll-controls[hidden] { display: none; }
.journey-scroll-controls button { display: grid; width: 1.55rem; height: 1.55rem; place-items: center; padding: 0px; border: 1px solid var(--line); border-radius: 50%; color: var(--scene-accent); background: color-mix(in srgb, var(--page) 78%, transparent); cursor: pointer; }
.journey-scroll-controls button:disabled { cursor: default; opacity: 0.28; }
[data-scroll-list] { overscroll-behavior-y: auto; scrollbar-color: color-mix(in srgb, var(--scene-accent) 48%, transparent) transparent; scrollbar-width: thin; }
.journey-hero-inner { justify-content: space-between; gap: clamp(0.9rem, 2.2vh, 1.5rem); }
.journey-hero-stage { display: flex; min-height: 0px; flex: 1 1 0%; align-items: center; padding-top: clamp(1.5rem, 3.5vh, 2.75rem); }
.journey-hero-copy { position: relative; z-index: 2; width: min(100%, 38rem); max-width: 38rem; container-type: inline-size; }
.journey-hero-copy h1 { color: transparent; background-image: ; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-color: ; margin: 0.45rem 0px 0px; font-size: clamp(3rem, 20.5cqi, 7.8rem); font-weight: 670; line-height: 0.88; letter-spacing: -0.075em; background-clip: text; }
.journey-intro { max-width: 33rem; margin: 1.15rem 0px 0px; color: var(--muted); font-size: clamp(0.92rem, 1.45vw, 1.04rem); line-height: 1.7; }
.journey-motto { display: flex; max-width: 31rem; align-items: baseline; gap: 0.55rem; margin: 0.7rem 0px 0px; color: var(--muted); font-family: var(--font-reading); font-size: 0.78rem; }
.journey-motto::before { width: 1.25rem; height: 1px; flex: 0 0 auto; background: var(--scene-accent); content: ""; }
.journey-motto blockquote, .journey-motto figcaption { margin: 0px; }
.journey-motto figcaption { font-family: var(--font-ui); font-size: 0.61rem; white-space: nowrap; }
.journey-hero-links { display: flex; align-items: baseline; justify-content: flex-start; gap: 1.2rem; margin-top: 0.9rem; }
.journey-hero-archives { display: flex; align-items: baseline; gap: 1.2rem; }
.journey-hero-archives a { display: inline-flex; align-items: center; gap: 0.4rem; color: var(--muted); font-size: 0.7rem; font-weight: 680; text-decoration: none; }
.journey-hero-archives a:is(:hover, :focus-visible) { color: var(--scene-accent); }
.journey-hero-links a span { color: inherit; }
.journey-profile-link { display: inline-flex; align-items: center; gap: 0.55rem; margin-top: 0px; color: var(--muted); font-size: 0.7rem; font-weight: 680; text-decoration: none; }
.journey-profile-link:is(:hover, :focus-visible) { color: var(--scene-accent); }
.journey-ridge-routes { position: relative; display: grid; width: 100%; grid-template-columns: repeat(4, minmax(0px, 1fr)); border-top: 1px solid var(--line); }
.journey-ridge-routes a { --route-color: var(--scene-accent); position: relative; display: grid; min-width: 0px; min-height: 4.6rem; grid-template-columns: auto auto minmax(0px, 1fr) auto; align-items: center; gap: 0.65rem; padding: 0.7rem clamp(0.75rem, 2vw, 1.35rem); color: var(--text); text-decoration: none; transition: background 180ms; }
.journey-ridge-routes a::before { position: absolute; top: -1px; right: 0px; left: 0px; height: 2px; background: var(--route-color); content: ""; opacity: 0; transform: scaleX(0.35); transition: opacity 180ms, transform 180ms; }
.journey-ridge-routes a + a { border-left: 1px solid var(--line); }
.journey-ridge-routes a i { width: 0.78rem; height: 0.78rem; border: 1px solid var(--route-color); border-radius: 50%; background: var(--page); box-shadow: 0 0 0 0.32rem color-mix(in srgb, var(--page) 85%, transparent); transition: background 180ms, transform 180ms; }
.journey-ridge-routes a span { color: var(--route-color); font-size: 0.68rem; font-weight: 780; }
.journey-ridge-routes a strong { font-family: var(--font-reading); font-size: clamp(1rem, 1.45vw, 1.3rem); font-weight: 610; white-space: nowrap; }
.journey-ridge-routes a small { color: var(--route-color); opacity: 0; transform: translate(-0.2rem, 0.2rem); transition: opacity 180ms, transform 180ms; }
.journey-ridge-routes a:hover i, .journey-ridge-routes a:focus-visible i, .snowline-hero[data-route-highlight="technical-ridge"] .journey-ridge-routes a:nth-of-type(1) i, .snowline-hero[data-route-highlight="study-terrace"] .journey-ridge-routes a:nth-of-type(2) i, .snowline-hero[data-route-highlight="snowfield-traverse"] .journey-ridge-routes a:nth-of-type(3) i, .snowline-hero[data-route-highlight="night-camp"] .journey-ridge-routes a:nth-of-type(4) i { background: var(--route-color); transform: scale(1.2); }
.journey-ridge-routes a:hover, .journey-ridge-routes a:focus-visible { background: color-mix(in srgb, var(--scene-accent) 7%, transparent); }
.journey-ridge-routes a:hover::before, .journey-ridge-routes a:focus-visible::before, .snowline-hero[data-route-highlight="technical-ridge"] .journey-ridge-routes a:nth-of-type(1)::before, .snowline-hero[data-route-highlight="study-terrace"] .journey-ridge-routes a:nth-of-type(2)::before, .snowline-hero[data-route-highlight="snowfield-traverse"] .journey-ridge-routes a:nth-of-type(3)::before, .snowline-hero[data-route-highlight="night-camp"] .journey-ridge-routes a:nth-of-type(4)::before { opacity: 1; transform: scaleX(1); }
.journey-ridge-routes a:hover small, .journey-ridge-routes a:focus-visible small { opacity: 1; transform: translate(0px, 0px); }
.journey-featured { width: min(100%, 31rem); margin-top: clamp(0.85rem, 2vh, 1.2rem); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.journey-featured > header { display: flex; align-items: end; justify-content: space-between; gap: 1rem; padding: 0.65rem 0px; }
.journey-featured h2 { margin: 0.15rem 0px 0px; font-size: 0.94rem; }
.journey-featured > header > a { display: inline-flex; align-items: center; gap: 0.5rem; color: var(--muted); font-size: 0.66rem; font-weight: 680; text-decoration: none; }
.journey-featured-track { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); column-gap: 1.15rem; border-top: 1px solid var(--line); }
.journey-featured-card { display: grid; min-height: 1.9rem; min-width: 0px; grid-template-columns: minmax(0px, 1fr) auto; align-items: center; gap: 0.4rem; padding: 0.3rem 0.1rem; text-decoration: none; transition: background 180ms; }
.journey-featured-card:nth-child(n+3) { border-top: 1px solid var(--line); }
.journey-featured-card:hover, .journey-featured-card:focus-visible { background: color-mix(in srgb, var(--surface) 55%, transparent); }
.journey-featured-card strong { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--font-reading); font-size: 0.85rem; font-weight: 570; line-height: 1.35; }
.journey-featured-card i { color: var(--muted); font-style: normal; }
.journey-featured-card[data-group="skill"] i { color: var(--ice-blue); }
.journey-featured-card[data-group="study"] i { color: var(--study-green); }
.journey-featured-card[data-group="life"] i { color: var(--dawn-coral); }
.journey-technical-grid { display: grid; grid-template-columns: minmax(15rem, 0.7fr) minmax(27rem, 1.3fr); gap: clamp(3rem, 8vw, 7rem); }
.journey-category-route, .journey-projects > div { display: grid; max-height: min(56vh, 32rem); overflow-y: auto; }
.journey-category-route a { display: grid; grid-template-columns: 1.8rem minmax(0px, 1fr) auto; align-items: center; gap: 0.65rem; min-height: 4rem; padding-block: 0.65rem; border-bottom: 1px solid var(--line); text-decoration: none; }
.journey-category-route a > span { color: var(--scene-accent); font-size: 0.61rem; font-weight: 740; }
.journey-category-route h4, .journey-project-card h4, .journey-life-map h3, .journey-notes h4, .journey-directory strong { margin: 0px; font-family: var(--font-reading); font-weight: 560; }
.journey-category-route h4 { font-size: clamp(1.05rem, 1.8vw, 1.35rem); }
.journey-category-route p, .journey-project-card p { margin: 0.2rem 0px 0px; color: var(--muted); font-size: 0.7rem; line-height: 1.45; }
.journey-category-route i, .journey-notes i, .journey-directory i, .journey-latest i { color: var(--scene-accent); font-style: normal; opacity: 0.7; transition: transform 180ms; }
.journey-category-route a:hover i, .journey-notes a:hover i, .journey-directory a:hover i, .journey-latest a:hover i { transform: translate(0.18rem, -0.18rem); }
.journey-project-card { display: grid; grid-template-columns: minmax(0px, 1fr); gap: 0.15rem; padding-block: 0.75rem; border-bottom: 1px solid var(--line); text-decoration: none; }
.journey-project-card small { color: var(--scene-accent); font-size: 0.57rem; font-weight: 760; letter-spacing: 0.12em; }
.journey-project-card h4 { margin-top: 0.16rem; font-size: clamp(1.15rem, 2vw, 1.6rem); }
.journey-project-card > p { margin-bottom: 0.2rem; }
.journey-progress { display: block; height: 1px; grid-column: 1 / -1; margin-top: 0.2rem; background: var(--line); }
.journey-progress i { display: block; height: 2px; transform: translateY(-0.5px); background: var(--scene-accent); }
.journey-ridge-routes a[data-hero-route="technical-ridge"] { --route-color: var(--ice-blue); }
.journey-ridge-routes a[data-hero-route="study-terrace"] { --route-color: var(--study-green); }
.journey-ridge-routes a[data-hero-route="snowfield-traverse"] { --route-color: var(--sun-gold); }
.journey-ridge-routes a[data-hero-route="night-camp"] { --route-color: var(--night-violet); }
.journey-life-content { display: block; }
.journey-life-content.has-no-categories { grid-template-columns: minmax(0px, 1fr); }
.journey-life-map { position: relative; margin-top: 1.6rem; padding-block: 0.8rem 1.25rem; }
.journey-life-map > [data-scroll-list] { display: grid; min-height: 15rem; align-items: start; grid-auto-columns: minmax(10rem, 1fr); grid-auto-flow: column; gap: clamp(1.2rem, 4vw, 3.5rem); margin-top: 0.65rem; overflow: auto hidden; scroll-snap-type: x mandatory; scrollbar-width: none; }
.journey-life-map > [data-scroll-list]::-webkit-scrollbar { display: none; }
.journey-horizontal-controls { justify-self: end; }
.journey-horizontal-controls button:first-child { transform: rotate(180deg); }
.journey-life-map a { position: relative; display: grid; min-height: 10rem; align-content: center; padding: 1.2rem 0px; text-decoration: none; scroll-snap-align: center; }
.journey-life-map small { color: var(--muted); font-size: 0.61rem; }
.journey-life-map h3 { margin-top: 0.25rem; font-size: clamp(1.25rem, 2.4vw, 2rem); }
.journey-life-map i { color: var(--scene-accent); font-style: normal; transition: transform 180ms; }
.journey-life-map a:nth-child(2n) { transform: translateY(4.6rem); }
.journey-life-map a:hover h3 { color: var(--scene-accent); }
.journey-life-map a:hover i { transform: translate(0.2rem, -0.2rem); }
.journey-latest { margin-top: clamp(2rem, 5vw, 4rem); }
.journey-latest > div { display: grid; max-height: 15rem; overflow-y: auto; }
.journey-latest a { display: grid; min-height: 4.7rem; grid-template-columns: 1.8rem minmax(0px, 1fr) auto; align-items: center; gap: 0.7rem; padding-block: 0.7rem; border-bottom: 1px solid var(--line); text-decoration: none; }
.journey-latest a > span, .journey-latest small { color: var(--muted); font-size: 0.59rem; }
.journey-latest strong { display: block; margin-top: 0.14rem; font-family: var(--font-reading); font-size: clamp(1.05rem, 2vw, 1.45rem); font-weight: 570; }
.has-no-categories .journey-latest > div { grid-template-columns: repeat(auto-fit, minmax(min(18rem, 100%), 1fr)); }
.has-no-categories .journey-latest a { min-height: 10rem; grid-template-columns: auto 1fr auto; align-content: end; padding: 1rem; border-left: 1px solid var(--line); }
.has-no-categories .journey-latest a:last-child { border-right: 1px solid var(--line); }
.journey-camp-grid { display: grid; grid-template-columns: minmax(0px, 1.15fr) minmax(19rem, 0.85fr); gap: clamp(3rem, 8vw, 7rem); }
