.friend-card > span { display: grid; width: 3rem; height: 3rem; place-items: center; border-radius: 50%; background: var(--accent-soft); color: var(--accent-strong); font-weight: 800; }
.friend-card h2 { margin: 0px 0px 0.35rem; }
.friend-card small { color: var(--accent); }
.friend-card i { position: absolute; top: 1rem; right: 1rem; color: var(--accent); font-style: normal; }
.content-page { width: min(100% - 2rem, 52rem); margin-inline: auto; }
.content-page-header { border-bottom: 1px solid var(--line); }
.content-page-body { margin-top: 3rem; }
.prose { min-width: 0px; color: var(--text); font-family: var(--font-reading); font-size: clamp(1rem, 1.6vw, 1.08rem); line-height: 1.95; }
.prose > article, .prose > article > :first-child { margin-top: 0px; }
.prose :where(h2, h3, h4) { scroll-margin-top: 6rem; font-family: var(--font-reading); line-height: 1.35; }
.prose h2 { margin: 3.2rem 0px 1.1rem; font-size: clamp(1.6rem, 4vw, 2.2rem); }
.prose h3 { margin: 2.4rem 0px 0.8rem; font-size: 1.35rem; }
.prose p, .prose ul, .prose ol, .prose blockquote { margin-block: 1.15rem; }
.prose ol { list-style-type: decimal; padding-inline-start: 1.75rem; }
.prose ol ol { list-style-type: lower-alpha; }
.prose ol ol ol { list-style-type: lower-roman; }
.prose blockquote { padding-left: 1.2rem; border-left: 2px solid var(--accent); color: var(--muted); }
.prose pre { overflow-x: auto; padding: 1.2rem; border: 1px solid rgb(45, 51, 59); border-radius: 0.7rem; background: rgb(13, 17, 23); color: rgb(240, 246, 252); font-size: 0.86rem; line-height: 1.7; }
.prose :not(pre) > code { padding: 0.12rem 0.35rem; border-radius: 0.3rem; background: var(--surface-subtle); color: var(--accent-strong); font-size: 0.88em; }
.prose table { display: block; width: 100%; overflow-x: auto; border-collapse: collapse; }
.prose th, .prose td { padding: 0.65rem 0.8rem; border: 1px solid var(--line); text-align: left; }
.prose img { max-width: 100%; height: auto; border-radius: 0.6rem; }
.content-callout, .content-toggle, .content-mindmap, .content-pdf { margin-block: 1.6rem; padding: 1rem 1.2rem; border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-left: 3px solid var(--accent); border-radius: 0.55rem; background: var(--surface); }
.content-callout-warning, .content-callout-danger { border-left-color: rgb(184, 107, 63); }
.content-callout > strong { display: block; margin-bottom: 0.45rem; font-family: var(--font-ui); }
.content-toggle summary { cursor: pointer; font-family: var(--font-ui); font-weight: 700; }
.content-columns { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr)); margin-block: 1.5rem; }
.content-columns[data-gap="small"] { gap: 0.75rem; }
