.mindmap-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.mindmap-toolbar button { padding: 0.45rem 0.75rem; border: 1px solid var(--line); border-radius: 999px; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.mindmap-svg { display: block; width: 100%; min-height: 28rem; margin-top: 0.8rem; border-radius: 0.4rem; background: var(--page); }
.mindmap-source { margin-top: 0.75rem; color: var(--muted); font-size: 0.78rem; }
.mindmap-source pre { white-space: pre-wrap; }
.content-anchor { scroll-margin-top: 6rem; }
.site-footer nav { display: flex; align-items: center; gap: 1rem; }
