:root { --page: #f5f7f6; --surface: #ffffff; --surface-subtle: #e9efed; --text: #172220; --muted: #687471; --line: #d9e1de; --accent: #2e7168; --accent-strong: #19574f; --accent-soft: #dfece8; --focus: #238578; --shadow: 0 18px 50px rgb(28 49 45 / 8%); --font-ui: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; --font-reading: 'Iowan Old Style', 'Noto Serif SC', 'Songti SC', Georgia, serif; --content-width: 72rem; }
:root[data-theme="dark"] { --page: #0d1211; --surface: #151c1a; --surface-subtle: #202b28; --text: #eaf0ed; --muted: #9eaca7; --line: #33413d; --accent: #8ec9bc; --accent-strong: #b7e0d7; --accent-soft: #1f3933; --focus: #8de0cf; --shadow: 0 18px 50px rgb(0 0 0 / 24%); }
*, ::before, ::after { box-sizing: border-box; }
html { background: var(--page); color: var(--text); font-family: var(--font-ui); scroll-behavior: smooth; }
body { min-width: 320px; min-height: 100vh; margin: 0px; background: var(--page); color: var(--text); line-height: 1.65; text-rendering: optimizelegibility; }
a {
  color: inherit; text-decoration-color: var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
  text-decoration-color: color-mix(in srgb, var(--accent) 55%, transparent);
}
  text-underline-offset: 0.22em;
}
a:hover { color: var(--accent-strong); }
a:focus-visible, button:focus-visible, summary:focus-visible {
  outline: 3px solid var(--focus);
  @supports (color: color-mix(in lab, red, red)) {
  outline: 3px solid color-mix(in srgb, var(--focus) 60%, transparent);
}
  outline-offset: 3px;
}
.shell { width: min(calc(100% - 2rem), var(--content-width)); margin-inline: auto; }
.skip-link { position: fixed; z-index: 100; inset: 0px auto auto 1rem; padding: 0.65rem 0.9rem; transform: translateY(-120%); border-radius: 0px 0px 0.5rem 0.5rem; background: var(--text); color: var(--page); }
.skip-link:focus { transform: translateY(0px); }
.site-header {
  position: sticky; z-index: 20; top: 0px; height: 4rem; border-bottom: 1px solid var(--line);
  @supports (color: color-mix(in lab, red, red)) {
  border-bottom: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
}
  background: var(--page);
  @supports (color: color-mix(in lab, red, red)) {
  background: color-mix(in srgb, var(--page) 88%, transparent);
}
  backdrop-filter: blur(14px);
}
.header-inner, .footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; }
.header-inner { position: relative; height: 100%; }
.full-viewport-page { height: 100dvh; overflow: hidden; }
.brand { font-weight: 760; letter-spacing: -0.04em; text-decoration: none; }
.brand span, .eyebrow { color: var(--accent); }
.nav-list, .site-menu-list, .home-sidebar ul { display: flex; gap: 1.25rem; margin: 0px; padding: 0px; list-style: none; }
.nav-list a { position: relative; display: block; padding-block: 1.3rem 1.2rem; color: var(--muted); font-size: 0.82rem; font-weight: 620; text-decoration: none; }
.nav-list a::after { position: absolute; right: 0px; bottom: 0.75rem; left: 0px; height: 1px; transform: scaleX(0); background: currentcolor; content: ""; transform-origin: right center; transition: transform 180ms; }
.nav-list a:hover, .nav-list a[aria-current="page"] { color: var(--text); }
.nav-list a:hover::after, .nav-list a[aria-current="page"]::after { transform: scaleX(1); transform-origin: left center; }
.header-actions { display: flex; align-items: center; gap: 0.4rem; }
.theme-toggle, .search-open, .language-menu summary, .site-menu > summary { display: grid; min-width: 2.25rem; min-height: 2.25rem; place-items: center; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--text); cursor: pointer; }
.desktop-navigation { margin-left: auto; }
.site-menu { position: relative; display: none; }
.site-menu > summary { padding: 0px; list-style: none; }
.site-menu > summary::-webkit-details-marker { display: none; }
.site-menu > summary span, .site-menu > summary span::before, .site-menu > summary span::after { display: block; width: 0.95rem; height: 1px; background: currentcolor; content: ""; transition: transform 180ms; }
.site-menu > summary span { position: relative; }
.site-menu > summary span::before { position: absolute; top: -0.3rem; }
.site-menu > summary span::after { position: absolute; top: 0.3rem; }
.site-menu[open] > summary span { background: transparent; }
.site-menu[open] > summary span::before { top: 0px; transform: rotate(45deg); }
.site-menu[open] > summary span::after { top: 0px; transform: rotate(-45deg); }
.site-menu nav {
  position: absolute; top: calc(100% + 0.75rem); right: 0px; width: min(22rem, -2rem + 100vw); padding: 0.75rem; border: 1px solid var(--line); border-radius: 0.65rem; background: var(--surface);
  @supports (color: color-mix(in lab, red, red)) {
  background: color-mix(in srgb, var(--surface) 96%, transparent);
}
  box-shadow: rgba(10, 24, 21, 0.18) 0px 24px 70px; backdrop-filter: blur(18px);
