.site-menu-list { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 1px; background: var(--line); }
.site-menu-list a { display: grid; grid-template-columns: 1.5rem 1fr; gap: 0.65rem; padding: 0.8rem; background: var(--surface); font-size: 0.85rem; font-weight: 650; text-decoration: none; }
