.site-menu-list span { color: var(--accent); font-size: 0.63rem; font-weight: 700; letter-spacing: 0.08em; }
.search-open { padding: 0px; font-size: 1.15rem; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px; }
.search-dialog { width: min(100% - 2rem, 46rem); max-height: min(82vh, 48rem); padding: 0px; overflow: hidden; border: 1px solid var(--line); border-radius: 1rem; background: var(--surface); color: var(--text); box-shadow: rgba(0, 0, 0, 0.28) 0px 30px 90px; }
