.search-dialog input[type="search"] { width: 100%; min-height: 3.25rem; padding: 0.7rem 0.9rem; border: 1px solid var(--line); border-radius: 0.65rem; background: var(--page); color: var(--text); font: inherit; }
.search-filters { justify-content: start; }
.search-filters label { display: grid; min-width: 9rem; gap: 0.3rem; color: var(--muted); font-size: 0.78rem; }
.search-filters select { min-height: 2.5rem; padding-inline: 0.7rem; border: 1px solid var(--line); border-radius: 0.5rem; background: var(--surface); color: var(--text); }
.search-status { min-height: 1.5rem; color: var(--muted); font-size: 0.85rem; }
.search-results { display: grid; gap: 0.65rem; margin: 0px; padding: 0px; list-style: none; }
.search-results a { display: block; padding: 0.9rem 1rem; border: 1px solid var(--line); border-radius: 0.7rem; text-decoration: none; }
.search-results p { margin: 0.3rem 0px 0px; color: var(--muted); font-size: 0.88rem; }
