.home-main { padding-block: clamp(3.5rem, 9vw, 7rem) 5rem; }
.intro { display: flex; align-items: end; justify-content: space-between; gap: 2rem; padding-bottom: clamp(3rem, 7vw, 5rem); border-bottom: 1px solid var(--line); }
.eyebrow { margin: 0px 0px 0.8rem; font-size: 0.76rem; font-weight: 750; letter-spacing: 0.12em; text-transform: uppercase; }
h1, h2 { font-family: var(--font-reading); text-wrap: balance; }
h1 { max-width: 17ch; margin: 0px; font-size: clamp(2.6rem, 7vw, 5.2rem); font-weight: 580; letter-spacing: -0.045em; line-height: 1.04; }
h2 { margin: 0px; font-size: clamp(1.35rem, 3vw, 1.9rem); font-weight: 620; letter-spacing: -0.025em; }
.intro-copy { max-width: 42rem; margin: 1.2rem 0px 0px; color: var(--muted); font-size: clamp(1rem, 2vw, 1.15rem); }
.button { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; min-height: 2.8rem; padding: 0.65rem 1rem; border-radius: 999px; background: var(--text); color: var(--page); font-weight: 700; text-decoration: none; }
.button:hover { background: var(--accent-strong); color: var(--page); }
.section { padding-block: 2.5rem; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-bottom: 1.25rem; }
.phase-badge { padding: 0.25rem 0.65rem; border-radius: 999px; background: var(--accent-soft); color: var(--accent-strong); font-size: 0.78rem; font-weight: 700; }
.featured-grid { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 1rem; }
.placeholder-card, .empty-state, .home-sidebar section { border: 1px solid var(--line); border-radius: 0.9rem; background: var(--surface); }
.placeholder-card { min-height: 10rem; padding: 1.25rem; }
.placeholder-card p, .empty-state p, .home-sidebar p { margin: 0px; color: var(--muted); }
.content-grid { display: grid; grid-template-columns: minmax(0px, 1fr) minmax(15rem, 0.34fr); gap: clamp(2rem, 6vw, 5rem); border-top: 1px solid var(--line); }
.article-list h2, .home-sidebar h2 { margin-bottom: 1rem; }
.empty-state { min-height: 15rem; padding: 1.4rem; }
.home-sidebar { display: grid; align-content: start; gap: 1rem; padding-block: 2.5rem; }
.home-sidebar section { padding: 1rem; }
.home-sidebar h2 { font-family: var(--font-ui); font-size: 0.95rem; }
.home-sidebar ul { flex-direction: column; gap: 0.45rem; }
.site-footer { border-top: 1px solid var(--line); color: var(--muted); font-size: 0.85rem; }
.footer-inner { min-height: 6rem; }
.status-page { min-height: calc(-10rem + 100vh); padding-block: clamp(5rem, 15vw, 10rem); }
.status-page h1 { margin-bottom: 1.25rem; }
.status-page p:not(.eyebrow) { max-width: 38rem; margin-bottom: 2rem; color: var(--muted); }
@media (max-width: 64rem) {
  .desktop-navigation { display: none; }
  .site-menu { display: block; }
  .header-actions { margin-left: auto; }
}
@media (max-width: 48rem) {
  .header-inner { gap: 0.75rem; }
  .intro { align-items: start; flex-direction: column; }
  .featured-grid, .content-grid { grid-template-columns: 1fr; }
  .home-sidebar { border-top: 1px solid var(--line); }
  .footer-inner { align-items: start; flex-direction: column; justify-content: center; gap: 0.25rem; }
  .footer-inner p { margin: 0px; }
}
@media (max-width: 30rem) {
  .site-menu-list { grid-template-columns: 1fr; }
  .language-menu summary { padding-inline: 0.55rem; }
}
